/bin/zsh -lc "python3 - <<'PY'
from bowling import BowlingGame


def play(rolls):
    game = BowlingGame()
    for pins in rolls:
        game.roll(pins)
    return game.score()

assert play([0] * 20) == 0
assert play([10] * 12) == 300
assert play([5, 5] * 10 + [5]) == 150
assert play([9, 0] * 10) == 90
assert play([10, 1, 9] + [0, 0] * 9) == 20
assert play([10, 10, 10] + [0, 0] * 8) == 60
assert play([10, 6, 4] + [0, 0] * 9) == 30

for rolls, bad, message in [
    ([5], 6, \"Pin count exceeds pins on the lane\"),
    ([10] * 9 + [5], 6, \"Pin count exceeds pins on the lane\"),
    ([10] * 9 + [10, 6], 5, \"Pin count exceeds pins on the lane\"),
    ([0, 0] * 10, 0, \"Cannot roll after game is over\"),
]:
    game = BowlingGame()
    for pins in rolls:
        game.roll(pins)
    try:
        game.roll(bad)
    except ValueError as exc:
        assert str(exc) == message, (str(exc), message)
    else:
        raise AssertionError(\"expected ValueError\")

for rolls in ([], [0], [10] * 9, [10] * 9 + [10, 0]):
    game = BowlingGame()
    for pins in rolls:
        game.roll(pins)
    try:
        game.score()
    except ValueError as exc:
        assert str(exc) == \"Score cannot be taken until the end of the game\"
    else:
        raise AssertionError(\"expected incomplete game\")

print(\"local rule checks passed\")
PY"

